"""Slicer-Einstellungen: aus 3MF-Projekten (Bambu Studio, Orca, Anycubic Slicer Next, PrusaSlicer) und aus G-Code; gleiche Einstellungen
geben denselben Hash, Namen zählen nicht; der Reiter im Inspektor liest sie aus der Datei. Die Dateien sind nachgebaut, nicht echt."""
import os
import tempfile
import zipfile

import muster
from muster import check
from fastapi.testclient import TestClient
from partatlas import slicer
from partatlas.main import erstelle_app

ORCA_GCODE = """; HEADER_BLOCK_START
; generated by OrcaSlicer 2.1.1 on 2026-10-01 at 10:00:00
; model printing time: 1h 2m 3s; total estimated time: 1h 10m 3s
; total filament weight [g] : 12.34
; HEADER_BLOCK_END
G28
G1 X10 Y10
; CONFIG_BLOCK_START
; layer_height = 0.2
; wall_loops = 3
; nozzle_temperature = 240,240
; print_settings_id = 0.20mm Standard @Anycubic
; sparse_infill_density = 15%
; CONFIG_BLOCK_END
"""

PRUSA_GCODE = """; generated by PrusaSlicer 2.8.0
G28
; filament used [g] = 7.5
; estimated printing time (normal mode) = 45m 10s
; prusaslicer_config = begin
; layer_height = 0.15
; perimeters = 2
; fill_density = 20%
; temperature = 215
; prusaslicer_config = end
"""

if __name__ == "__main__":
    tmp = tempfile.mkdtemp()

    # -- 3MF-Projekt (Bambu/Orca): Werte, Slicer, abweichende Objekte
    p = os.path.join(tmp, "Halter.3mf")
    muster.dreimf(p, einstellungen=muster.BAMBU_EINSTELLUNGEN, objekt_einstellungen={"name": "Arm", "wall_loops": "5"})
    e = slicer.aus_3mf(p)
    check("3MF: alle Werte gelesen, Slicer aus den Metadaten", e["werte"]["layer_height"] == "0.2" and e["slicer"] == "BambuStudio-01.09.00.70")
    w = {z["name"]: z["wert"] for g in slicer.wichtigste(e["werte"]) for z in g["zeilen"]}
    check("Das Wichtigste in Worten mit Einheit; Bett-Temperatur zur gewählten Platte (texturiert: 70, nicht 80)",
          w["Schichthöhe"] == "0.2 mm" and w["Wände"] == "3" and w["Oben / unten"] == "5 / 4 Schichten" and w["Dichte"] == "15%"
          and w["Düse"] == "240 °C" and w["Bett"] == "70 °C" and w["Drucker"] == "Bambu Lab P1S 0.4 nozzle" and w["Stützen"] == "aus")
    check("Abweichende Einstellungen einzelner Objekte", e["objekte"] == [{"name": "Arm", "werte": {"wall_loops": "5"}}])
    nur = os.path.join(tmp, "Nur.3mf")
    muster.dreimf(nur)
    check("3MF ohne Einstellungen (reine Geometrie): None", slicer.aus_3mf(nur) is None)
    pe = os.path.join(tmp, "Prusa.3mf")
    with zipfile.ZipFile(pe, "w") as z:
        z.writestr("3D/3dmodel.model", "<model/>")
        z.writestr("Metadata/Slic3r_PE.config", "; layer_height = 0.15\n; perimeters = 2\n")
    check("PrusaSlicer-3MF: Slic3r_PE.config", slicer.aus_3mf(pe)["werte"] == {"layer_height": "0.15", "perimeters": "2"})

    # -- G-Code
    g1 = os.path.join(tmp, "a.gcode")
    open(g1, "w").write(ORCA_GCODE)
    g = slicer.aus_gcode(g1)
    check("G-Code (Orca/Anycubic): Konfigurationsblock, Gewicht und Druckzeit aus dem Kopf",
          g["werte"]["wall_loops"] == "3" and g["kopf"] == {"gewicht_g": 12.34, "dauer_s": 3723} and g["slicer"].startswith("OrcaSlicer"))
    g2 = os.path.join(tmp, "b.gcode")
    open(g2, "w").write(PRUSA_GCODE)
    g = slicer.aus_gcode(g2)
    check("G-Code (PrusaSlicer): Konfiguration am Ende, Gewicht und Zeit", g["werte"]["perimeters"] == "2"
          and g["kopf"] == {"gewicht_g": 7.5, "dauer_s": 2710})
    g3 = os.path.join(tmp, "cura.gcode")
    open(g3, "w").write(";FLAVOR:Marlin\n;TIME:6666\n;Filament used: 2.5m\n;Layer height: 0.2\nG28\nG1 X10 Y10\n")
    check("G-Code (Cura): die Druckzeit steht als „;TIME:“ in Sekunden im Kopf", slicer.aus_gcode(g3)["kopf"] == {"dauer_s": 6666})
    vier = os.path.join(tmp, "vier.gcode")
    open(vier, "w").write("; generated by AnycubicSlicerNext 1.3.4.0 on 2026-01-12\nG28\n; filament used [g] = 2.89, 0.00, 0.00, 0.00\n; total filament used [g] = 2.89\n"
                          "; CONFIG_BLOCK_START\n; filament_settings_id = \"PLA a\";\"ABS b\";\"ASA c\";\"TPU d\"\n; filament_type = PLA;ABS;ASA;TPU\n; layer_height = 0.28\n; CONFIG_BLOCK_END\n")
    g = slicer.aus_gcode(vier)
    check("G-Code mit vier Filament-Plätzen, einer benutzt: nur dieses Filament steht in den Werten",
          g["werte"]["filament_type"] == "PLA" and g["werte"]["filament_settings_id"] == '"PLA a"' and g["werte"]["layer_height"] == "0.28")
    gross = os.path.join(tmp, "gross.gcode")
    kopf, rumpf, schluss = ORCA_GCODE.split("G28\nG1 X10 Y10\n")[0], "G1 X1 Y1\n" * 400000, ORCA_GCODE.split("G1 X10 Y10\n")[1]
    open(gross, "w").write(kopf + rumpf + schluss)
    check("Grosser G-Code: der Block am Ende wird gefunden, ohne alles zu lesen", slicer.aus_gcode(gross, grenze=1 << 20)["werte"].get("wall_loops") == "3")

    # -- Hash und Unterschiede
    a = {"layer_height": "0.2", "wall_loops": "3", "print_settings_id": "Mein Profil", "version": "1.9"}
    b = {"layer_height": "0.2", "wall_loops": "3", "print_settings_id": "Kopie von Mein Profil", "version": "2.0"}
    check("Gleiche Einstellungen, anderer Profilname und Fassung: derselbe Hash", slicer.profil_hash(a) == slicer.profil_hash(b))
    c = {**a, "wall_loops": "4"}
    check("Anderer Wert: anderer Hash; der Unterschied ist genau dieser Wert",
          slicer.profil_hash(a) != slicer.profil_hash(c) and slicer.unterschiede(a, c) == [{"schluessel": "wall_loops", "a": "3", "b": "4"}])

    # -- Reiter im Inspektor: aus der Datei gelesen, nicht aus dem Graphen
    samm = os.path.join(tmp, "3D")
    os.makedirs(samm)
    muster.dreimf(os.path.join(samm, "Halter.3mf"), einstellungen=muster.BAMBU_EINSTELLUNGEN)
    muster.dreimf(os.path.join(samm, "Nur.3mf"))
    with TestClient(erstelle_app(os.path.join(tmp, "bestand"), prozesse=2)) as cl:
        z = cl.app.state.zustand
        cl.post("/api/wurzeln", json={"pfad": samm})
        z["scanner"].warten(120)
        ids = {m["name"]: m["id"] for m in cl.get("/api/modelle").json()}
        r = cl.get(f"/api/modelle/{ids['Halter']}/slicer").json()
        check("Reiter: das Wichtigste und alle Werte", not r["leer"] and r["wichtig"][0]["gruppe"] == "Drucker"
              and len(r["alle"]) == len(muster.BAMBU_EINSTELLUNGEN))
        r = cl.get(f"/api/modelle/{ids['Nur']}/slicer").json()
        check("Reine Geometrie: leer, mit Grund", r["leer"] and "Geometrie" in r["grund"])
        h = cl.get(f"/api/modelle/{ids['Halter']}").json()["hash"]
        d = z["katalog"].db.get_node(f"PART_GEOMETRY/{h}")
        check("Die Einstellungen stehen nicht im Graphen", "layer_height" not in str(d))
    muster.ende()
